INSERT INTO `chat_message` VALUES (93, 33, 'assistant', '你好！有什么可以帮你的吗？', NULL, '[]', '[]', NULL, NULL, NULL, NULL, '2026-05-12 17:26:36');
INSERT INTO `chat_message` VALUES (94, 34, 'user', '建模档出图标准怎么设置', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-12 17:29:08');
INSERT INTO `chat_message` VALUES (95, 34, 'assistant', '建模档出图标准设置需按以下步骤操作：\n\n1. **前置条件**：先打开配置表，定位至「基本属性」工作表，方可修改模具名称、产品厚度、加工说明等公共信息；否则这些字段将为空或保留旧值。  \n2. 填写**模具编号**（必填，唯一标识整套模具数据）；  \n3. **选择出图零件类型**：根据需求**有且仅选一种**——「常规出图零件」（高精度全特征图）或「轻量化出图零件」（简化交付/快速审阅），不可混用或遗漏；  \n4. 选择**投影视角**（第一视角或第三视角），必须在视图选择前完成；  \n5. 选择要投影的视图（默认主/右/前视图），并勾选球标图、线割涂色（默认红色186）、研磨符号等；  \n6. 设置**球标大小**，勾选是否添加加工说明、英文注解、英制牙，选择做深/掏留、槽注解等；  \n7. 填写**图纸路径**（默认在当前文件夹创建DWG文件夹），确认后点击“确定”出图。  \n\n（参考: 建模出图工具 - dependency / caution / prerequisite / feature_detail）', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/a034aebacbe64c33b87503e9ae189b31.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/d0972d1d8a4c40d99415d1b0af32bedb.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/cae11a9be14d4c6d8093040d8705b7c1.png\"]', '[{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.7012636},{\"featureName\":\"建模出图工具\",\"chunkType\":\"caution\",\"score\":0.6998169},{\"featureName\":\"建模出图工具\",\"chunkType\":\"prerequisite\",\"score\":0.6783732},{\"featureName\":\"建模出图工具\",\"chunkType\":\"feature_detail\",\"score\":0.67807347}]', NULL, NULL, NULL, NULL, '2026-05-12 17:29:17');
INSERT INTO `chat_message` VALUES (96, 35, 'user', '你上面问题说提到的图纸路径，默认在哪个路径下？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-12 19:16:35');
INSERT INTO `chat_message` VALUES (97, 35, 'assistant', '默认图纸路径为：**“图档当前文件夹创建DWG文件夹”**。\n\n但请注意：\n- 该路径需具备**写入权限**；\n- 所在磁盘必须**空间充足**；\n- **不推荐直接使用默认路径**，因其可能因权限或空间问题导致出图失败且无提示。\n\n✅ 正确做法：手动填写一个**本地可写、路径不含中文/特殊字符、空间充足的绝对路径**，例如：`D:\\Drawings\\`。\n\n(参考: 建模出图工具-caution)', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/b910649ba6e147578475c7ae5468d788.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/a034aebacbe64c33b87503e9ae189b31.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cada2dfa489471d831ca21cc441a07b.png\"]', '[{\"featureName\":\"建模出图工具\",\"chunkType\":\"caution\",\"score\":0.63269055},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.5566717},{\"featureName\":\"出图预设\",\"chunkType\":\"operation_guide\",\"score\":0.5465771},{\"featureName\":\"建模档合并订料\",\"chunkType\":\"dependency\",\"score\":0.5423082}]', NULL, NULL, NULL, NULL, '2026-05-12 19:16:47');
INSERT INTO `chat_message` VALUES (98, 34, 'user', '你上面问题说提到的图纸路径，默认在哪个路径下？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-12 19:22:49');
INSERT INTO `chat_message` VALUES (99, 34, 'assistant', '默认图纸路径为：**“图档当前文件夹创建DWG文件夹”**，即在您当前打开的建模档所在目录下，自动生成一个名为 `DWG` 的子文件夹作为输出路径。\n\n⚠️ 注意事项：\n- 该路径需具备**写入权限**（不可为只读）；\n- 不建议使用**网络映射盘符**（易因连接不稳定导致出图失败）；\n- 路径中**不能含中文或特殊字符**；\n- 磁盘需有**充足剩余空间**，否则出图失败且无明确提示。\n\n✅ 推荐做法：手动指定一个本地绝对路径，例如：  \n`D:\\Drawings\\` 或 `C:\\MyProjects\\DWG\\`\n\n（参考: 建模出图工具 - caution）', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/b910649ba6e147578475c7ae5468d788.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/f790c88756f145428acec2fc31c64039.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/a034aebacbe64c33b87503e9ae189b31.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cada2dfa489471d831ca21cc441a07b.png\"]', '[{\"featureName\":\"建模出图工具\",\"chunkType\":\"caution\",\"score\":0.63269055},{\"featureName\":\"建模出图工具\",\"chunkType\":\"dependency\",\"score\":0.5566717},{\"featureName\":\"出图预设\",\"chunkType\":\"operation_guide\",\"score\":0.5465771},{\"featureName\":\"出图预设\",\"chunkType\":\"feature_intro\",\"score\":0.54125607}]', NULL, NULL, NULL, NULL, '2026-05-12 19:22:56');
INSERT INTO `chat_message` VALUES (100, 36, 'user', '我登陆蓝U的时候，总是说我已经登录了，要怎么处理？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-13 14:47:43');
INSERT INTO `chat_message` VALUES (101, 36, 'assistant', '关于“登录蓝U时提示‘已登录’”的问题，我目前的知识库暂未覆盖完整答案。需要我帮您提交工单，让技术人员进一步协助吗？', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/03/01/135f645e3ef54410b6167b39d47db15b.png\",\"http://36.150.236.251:9000/agent-demo/2026/03/01/faf2346e44854d98839f1be0b0e4512c.png\"]', '[{\"featureName\":\"出图预设\",\"chunkType\":\"error_solution\",\"score\":0.5271341},{\"featureName\":\"快速涂色\",\"chunkType\":\"error_solution\",\"score\":0.50909626},{\"featureName\":\"出图预设\",\"chunkType\":\"prerequisite\",\"score\":0.5083445}]', NULL, NULL, NULL, NULL, '2026-05-13 14:47:54');
INSERT INTO `chat_message` VALUES (102, 37, 'user', '我登陆蓝U的时候，总是说我已经登录了，要怎么处理？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-13 15:00:42');
INSERT INTO `chat_message` VALUES (103, 37, 'assistant', '这个问题属于登录异常。根据知识库信息，您可以按以下步骤处理：\n\n1. **等待约15秒**后重新尝试登录；  \n2. 检查当前网络连接是否正常；  \n3. 若仍失败，可联系运维人员进一步协助。\n\n（参考: 登录蓝U失败，提示已在其他电脑登录）', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/03/01/135f645e3ef54410b6167b39d47db15b.png\",\"http://36.150.236.251:9000/agent-demo/2026/03/01/faf2346e44854d98839f1be0b0e4512c.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\" 登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.7879374},{\"featureName\":\" 登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.74828964},{\"featureName\":\" 获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.63392437},{\"featureName\":\"出图预设\",\"chunkType\":\"error_solution\",\"score\":0.5271341},{\"featureName\":\"快速涂色\",\"chunkType\":\"error_solution\",\"score\":0.50909626},{\"featureName\":\"出图预设\",\"chunkType\":\"prerequisite\",\"score\":0.5083445}]', NULL, NULL, NULL, NULL, '2026-05-13 15:00:53');
INSERT INTO `chat_message` VALUES (104, 38, 'user', '使用BOM导出Excel的表格为什么行数是乱的？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-13 15:03:55');
INSERT INTO `chat_message` VALUES (105, 38, 'assistant', '您遇到的是**BOM导出Excel表格后行数错乱**的问题。\n\n可能原因及解决步骤如下：\n\n1. **分页行数设置超标**：导出时“分页行数”超过系统允许最大值（20行），导致数据截断或错位。  \n2. **未先扫描BOM表**：导出操作依赖扫描生成的数据源，未扫描则导出内容异常。\n\n✅ **解决方法**：  \n- 重新操作：**步骤四前确保已扫描所有实体**；  \n- 在“步骤三”中勾选“分页”后，**将分页行数严格设为≤20**（推荐20或更低，如15）；  \n- 避免惯性输入40、30等值。\n\n⚠️ **预防措施**：导出前务必检查分页行数输入框，默认值或历史值若＞20需手动修正。（参考: BOM工具-error_solution）', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/879b77d17614425d8e8ad54ca4ce5fdc.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\" 使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.8884482},{\"featureName\":\" 获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.33482787},{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.9097379},{\"featureName\":\"BOM工具\",\"chunkType\":\"faq\",\"score\":0.74615943},{\"featureName\":\"BOM工具\",\"chunkType\":\"caution\",\"score\":0.7353104},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.6894391}]', NULL, NULL, NULL, NULL, '2026-05-13 15:04:02');
INSERT INTO `chat_message` VALUES (106, 39, 'user', '快速涂色功能具体如何使用？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-13 15:10:34');
INSERT INTO `chat_message` VALUES (107, 39, 'assistant', '快速涂色功能使用步骤如下：\n\n1. **选择设计标准**：进入功能后，先根据品牌选择对应的设计标准（如启泰）；若未设置出图标准，系统将弹出提示。  \n2. **勾选目标图层**：在图层管理中**勾选需要更改颜色的体/孔/键槽/面所在的图层**（此为过滤器生效前提）。  \n3. **启动过滤器**：单击“选择体”“选择孔”等对应过滤器，系统识别特征并显示红/绿/橙/蓝状态字体。  \n4. **检查并配置**：打开“特征注解表”，点击“打开配置表”，对特征参数（图层、材质类型、材质颜色）进行配置。  \n5. **一键涂色**：确认配置无误后，点击**“一键涂色”**按钮执行批量上色（若按钮置灰，请检查前序步骤是否完成）。\n\n（参考: 快速涂色-feature_detail & dependency）', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/bd923242a74d46449dcaa85abb0f5f49.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/1d37949231844396aff4304cb177cc48.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/5e42e601abee40ca862ff79a70608953.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7179f4f725e947338d00ba51aa0f5e6d.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\" 获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.34567133},{\"featureName\":\" 登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.33836308},{\"featureName\":\"快速涂色\",\"chunkType\":\"feature_detail\",\"score\":0.8091879},{\"featureName\":\"快速涂色\",\"chunkType\":\"dependency\",\"score\":0.80521053}]', NULL, NULL, NULL, NULL, '2026-05-13 15:10:40');
INSERT INTO `chat_message` VALUES (108, 40, 'user', '使用BOM导出Excel的表格为什么行数是乱的？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-13 15:13:40');
INSERT INTO `chat_message` VALUES (109, 40, 'assistant', '您遇到的是**BOM导出Excel后行数错乱**的问题。\n\n可能原因：\n1. **分页行数设置超标**：在步骤三中将“分页行数”设为＞20（如25、40），而系统实际仅支持≤20行/页，超限会导致分页逻辑异常、行序错位；\n2. **未扫描实体即导出**：导出前未执行“扫描所有实体”或“选择实体生成”，导致数据源不完整，导出内容错行或缺失。\n\n解决步骤：\n1. 重新进入BOM工具 → **步骤四前务必先完成“扫描所有实体”**；\n2. 进入**步骤三** → 勾选“分页”后，将“分页行数”**手动改为 ≤20（推荐设为20或15）**；\n3. 再执行导出EXCEL → 后续转TXT也不会乱码。\n\n预防措施：导出前养成检查“分页行数≤20”的习惯，避免依赖默认值或惯性输入大数值。（参考: BOM工具-error_solution）', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/879b77d17614425d8e8ad54ca4ce5fdc.png\"]', '[{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.9097379},{\"featureName\":\"BOM工具\",\"chunkType\":\"faq\",\"score\":0.74615943},{\"featureName\":\"BOM工具\",\"chunkType\":\"caution\",\"score\":0.7353104},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.6894391}]', NULL, NULL, NULL, NULL, '2026-05-13 15:13:47');
INSERT INTO `chat_message` VALUES (110, 41, 'user', '使用BOM导出Excel的表格为什么行数是乱的？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-13 15:16:46');
INSERT INTO `chat_message` VALUES (111, 41, 'assistant', '您遇到的是**BOM导出Excel后行数错乱**的问题。\n\n可能原因：\n1. **分页行数设置超标**：导出时“分页行数”设为＞20（如25、30、40），超出系统单页最大允许行数（20），导致分页逻辑异常、数据截断或错位；\n2. **未先扫描实体即导出**：BOM数据源未通过“扫描所有实体”生成，导出内容基于空或不完整内存数据集。\n\n解决步骤：\n1. **重新操作**：进入BOM工具 → 步骤三勾选“分页” → 将**分页行数严格设为≤20**（推荐20或15）；\n2. **确保前置扫描**：在导出前，务必执行“步骤四：扫描所有实体出BOM表”（或选择实体生成），保证数据源完整。\n\n预防措施：导出前始终检查分页行数输入框，默认值或历史惯性填入“40”是常见诱因。(参考: BOM工具-error_solution)', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/879b77d17614425d8e8ad54ca4ce5fdc.png\"]', '[{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.9097379},{\"featureName\":\"BOM工具\",\"chunkType\":\"faq\",\"score\":0.74615943},{\"featureName\":\"BOM工具\",\"chunkType\":\"caution\",\"score\":0.7353104},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.6894391}]', NULL, NULL, NULL, NULL, '2026-05-13 15:16:59');
INSERT INTO `chat_message` VALUES (112, 42, 'user', '我登陆蓝U的时候，总是说我已经登录了，要怎么处理？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-13 15:33:44');
INSERT INTO `chat_message` VALUES (113, 43, 'user', '使用BOM导出Excel的表格为什么行数是乱的？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-13 15:46:44');
INSERT INTO `chat_message` VALUES (114, 43, 'assistant', '您遇到的是**BOM导出Excel表格后行数错乱**的问题。\n\n可能原因及解决步骤如下：\n\n1. **分页行数设置超标**：导出时“分页行数”超过系统允许的最大值（**必须≤20**），导致Excel分页逻辑异常，进而引发TXT转换或显示时行序错乱。  \n2. **未先扫描BOM数据源**：若跳过“扫描所有实体出BOM表”步骤直接导出，内存中无完整数据，导出内容不全或格式错位。\n\n✅ **解决方法**：  \n- 确保执行**步骤四：“扫描所有实体出BOM表”**（知识片段4）；  \n- 进入导出设置，将**分页行数严格设为≤20**（推荐20或更低，如15），切勿填40、30等（知识片段1/2/3）；  \n- 重新导出Excel，再转TXT即可避免乱码与行序错误。\n\n📌 **预防措施**：导出前务必检查分页行数输入框，默认值或习惯性填写“40”是该问题的主因。（参考: BOM工具-error_solution）', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/879b77d17614425d8e8ad54ca4ce5fdc.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.8884482},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.33482787},{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.9097379},{\"featureName\":\"BOM工具\",\"chunkType\":\"faq\",\"score\":0.74615943},{\"featureName\":\"BOM工具\",\"chunkType\":\"caution\",\"score\":0.7353104},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.6894391}]', NULL, NULL, NULL, NULL, '2026-05-13 15:46:59');
INSERT INTO `chat_message` VALUES (115, 44, 'user', '我登陆蓝U的时候，总是说我已经登录了，要怎么处理？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-13 15:48:39');
INSERT INTO `chat_message` VALUES (116, 44, 'assistant', '登录蓝U时提示“已在其他电脑登录”，可按以下步骤处理：\n\n1. **等待约15秒**后，重新尝试登录；  \n2. 检查本地网络连接是否正常（如Wi-Fi或网线）；  \n3. 若仍失败，可**重启蓝U客户端**后再试；  \n4. 如问题持续，建议联系运维人员协助排查多端登录冲突或会话异常。\n\n（参考: 用户常见问题-FAQ 1）', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/03/01/135f645e3ef54410b6167b39d47db15b.png\",\"http://36.150.236.251:9000/agent-demo/2026/03/01/faf2346e44854d98839f1be0b0e4512c.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/dba55efb05de42f5818f1967e303eb47.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"登录蓝U失败，提示已在其他电脑登录。\",\"chunkType\":\"FAQ\",\"score\":0.7879374},{\"featureName\":\"登录蓝U提示密码错误\",\"chunkType\":\"FAQ\",\"score\":0.74828964},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.63392437},{\"featureName\":\"出图预设\",\"chunkType\":\"error_solution\",\"score\":0.5271341},{\"featureName\":\"快速涂色\",\"chunkType\":\"error_solution\",\"score\":0.50909626},{\"featureName\":\"出图预设\",\"chunkType\":\"prerequisite\",\"score\":0.5083445}]', NULL, NULL, NULL, NULL, '2026-05-13 15:48:52');
INSERT INTO `chat_message` VALUES (117, 45, 'user', '使用BOM导出Excel的表格为什么行数是乱的？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-13 15:49:59');
INSERT INTO `chat_message` VALUES (118, 45, 'assistant', '您遇到的是**BOM导出Excel后行数错乱**的问题。\n\n可能原因及解决步骤如下：\n\n1. **分页行数设置超标**：导出时“分页行数”超过系统允许最大值（20行），导致分页逻辑异常、数据错位或截断。  \n2. **未扫描即导出**：未先执行“扫描所有实体生成BOM表”，导出基于空或不完整数据源。\n\n✅ **解决方法**：  \n- 确保已执行**步骤四：扫描所有实体生成BOM表**；  \n- 进入导出设置，将**分页行数严格设为 ≤20**（推荐20或更低，如15）；  \n- 重新导出Excel，再转TXT（若需）。\n\n⚠️ **预防措施**：操作指南第四步勾选“分页”时，务必手动检查并修改分页行数输入框，默认值或惯性填入“40”会直接触发该问题。(参考: BOM工具-error_solution)', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/02/28/879b77d17614425d8e8ad54ca4ce5fdc.png\",\"http://36.150.236.251:9000/agent-demo/2026/05/13/0b1f970b3c8649ee8b72959b1db8f719.png\"]', '[{\"featureName\":\"使用BOM导出Excel的表格为什么行数是乱的？\",\"chunkType\":\"FAQ\",\"score\":0.8884482},{\"featureName\":\"获取许可证失败报错\",\"chunkType\":\"FAQ\",\"score\":0.33482787},{\"featureName\":\"BOM工具\",\"chunkType\":\"error_solution\",\"score\":0.9097379},{\"featureName\":\"BOM工具\",\"chunkType\":\"faq\",\"score\":0.74615943},{\"featureName\":\"BOM工具\",\"chunkType\":\"caution\",\"score\":0.7353104},{\"featureName\":\"BOM工具\",\"chunkType\":\"dependency\",\"score\":0.6894391}]', NULL, NULL, NULL, NULL, '2026-05-13 15:50:05');
INSERT INTO `chat_message` VALUES (119, 46, 'user', '我在使用快速涂色功能的时候,为什么上色功能失败？弹出个提示框,说是找不到配置表。这个问题要怎么解决？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-14 20:04:09');
INSERT INTO `chat_message` VALUES (120, 46, 'assistant', '您在使用「快速涂色」时因**未设置出图标准，导致系统找不到配置表而上色失败**。\n\n可能原因（按优先级）：\n1. **未选择设计标准**（如“启泰”），致使系统无法加载特征注解表和材质颜色表；\n2. 已设置标准但配置表未正确关联或路径异常。\n\n解决步骤：\n1. 进入【建模档出图标准设置】；\n2. 手动选择对应品牌的设计标准（例如：选择“启泰”）；\n3. 再依次打开【特征注解表】和【材质颜色表】确认可正常加载。\n\n如何预防：  \n每次启动「快速涂色」前，务必先完成设计标准设置；建议在项目初始化阶段将常用标准设为默认。（参考:快速涂色-error_solution）', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/03/01/ad93eac41af84147a3eaba3b438d4673.png\",\"http://36.150.236.251:9000/agent-demo/2026/03/01/faf2346e44854d98839f1be0b0e4512c.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cada2dfa489471d831ca21cc441a07b.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\"]', '[{\"featureName\":\"快速涂色\",\"chunkType\":\"error_solution\",\"score\":0.8853893},{\"featureName\":\"快速涂色\",\"chunkType\":\"faq\",\"score\":0.8028871},{\"featureName\":\"快速涂色\",\"chunkType\":\"prerequisite\",\"score\":0.7545009}]', NULL, NULL, NULL, NULL, '2026-05-14 20:04:21');
INSERT INTO `chat_message` VALUES (121, 46, 'user', '我试了，没有效果。这个提个工单', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-14 20:05:04');
INSERT INTO `chat_message` VALUES (122, 46, 'assistant', '好的,我来帮您提交工单,请稍候。  \n好的，我来帮您提交工单，请稍候。  \n✅ 工单已成功提交，编号：**TK-20260514-0001**  \n您可随时用该编号查询处理进度。', NULL, '[]', '[{\"featureName\":\"快速涂色\",\"chunkType\":\"error_solution\",\"score\":0.5869399}]', NULL, NULL, NULL, NULL, '2026-05-14 20:05:09');
INSERT INTO `chat_message` VALUES (123, 47, 'user', '我在使用快速涂色功能的时候,为什么上色功能失败？弹出个提示框,说是找不到配置表。这个问题要怎么解决？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-14 20:44:32');
INSERT INTO `chat_message` VALUES (124, 47, 'assistant', '您在使用「快速涂色」时遇到“找不到配置表”提示，导致上色失败。\n\n可能原因（按优先级）：\n1. **未设置建模档出图标准**（最常见）——系统无法定位特征注解表和材质颜色表；\n2. 已设置标准但对应标准的配置表尚未加载或损坏；\n3. 配置表路径异常或权限不足。\n\n解决步骤：\n1. 进入【建模档出图标准设置】；\n2. 手动选择对应品牌的设计标准（如“启泰”）；\n3. 完成后，再进入「快速涂色」→ 依次检查并打开【特征注解表】和【材质颜色表】，确认可正常加载。\n\n预防措施：每次启动「快速涂色」前，务必先完成出图标准设置；建议在项目初始化阶段固化默认标准。(参考:快速涂色-error_solution)', NULL, '[\"http://36.150.236.251:9000/agent-demo/2026/03/01/ad93eac41af84147a3eaba3b438d4673.png\",\"http://36.150.236.251:9000/agent-demo/2026/03/01/faf2346e44854d98839f1be0b0e4512c.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/7cada2dfa489471d831ca21cc441a07b.png\",\"http://36.150.236.251:9000/agent-demo/2026/02/28/4bf44f6d7afe4885b35840f6e6a7ac5a.png\"]', '[{\"featureName\":\"快速涂色\",\"chunkType\":\"error_solution\",\"score\":0.8853893},{\"featureName\":\"快速涂色\",\"chunkType\":\"faq\",\"score\":0.8028871},{\"featureName\":\"快速涂色\",\"chunkType\":\"prerequisite\",\"score\":0.7545009}]', NULL, NULL, NULL, NULL, '2026-05-14 20:44:44');
